import * as Core from '.';
class TimeWithObserver extends Core.Time {
    _observer;
    constructor(observer) {
        super();
        this._observer = observer;
    }
    addHours(hours = 1) {
        super.addHours(hours);
        this.updated();
    }
    subHours(hours = 1) {
        super.subHours(hours);
        this.updated();
    }
    updated() {
        this._observer.updated();
    }
}
export default TimeWithObserver;
